// energy/degradation sketch for: Ultimaker Cura
let c = 1.0; const samples = [];
for (let i = 0; i < 646; i++) { c *= 0.99976; if (i % 100 === 0) samples.push(+c.toFixed(4)); }
console.log(JSON.stringify({ cycles: 646, retention: +c.toFixed(4), samples: samples,
  eolReached: c < 0.8 }));

